import math

import pytest


def fact(n: int) -> int:
    """Return n! (the product of integers 1..n); fact(0) == 1.

    Raises ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result


def test_fact_base_cases() -> None:
    assert fact(0) == 1
    assert fact(1) == 1


def test_fact_small_values() -> None:
    assert fact(2) == 2
    assert fact(3) == 6
    assert fact(5) == 120
    assert fact(10) == 3628800


def test_fact_large_value() -> None:
    assert fact(20) == 2432902008176640000
    assert fact(30) == math.factorial(30)


def test_fact_matches_math_factorial() -> None:
    for n in range(0, 25):
        assert fact(n) == math.factorial(n)


def test_fact_recurrence() -> None:
    for n in range(1, 25):
        assert fact(n) == n * fact(n - 1)


def test_fact_negative_raises() -> None:
    with pytest.raises(ValueError):
        fact(-1)
    with pytest.raises(ValueError):
        fact(-100)
